"use client"

import { useEffect, useRef, useState } from "react";
import { useChatStore, Message } from "@/stores/ChatStore";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { SendHorizontal, User, Bot, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";


interface ChatContainerProps {
    chatId: string;
}

export function ChatContainer({ chatId }: ChatContainerProps) {
    const chat = useChatStore((state) => state.getChatById(chatId));
    const addMessage = useChatStore((state) => state.addMessage);
    const [inputValue, setInputValue] = useState("");
    const scrollRef = useRef<HTMLDivElement>(null);

    // Auto-scroll to bottom when messages change
    useEffect(() => {
        if (scrollRef.current) {
            const scrollContainer = scrollRef.current.querySelector('[data-radix-scroll-area-viewport]');
            if (scrollContainer) {
                scrollContainer.scrollTop = scrollContainer.scrollHeight;
            }
        }
    }, [chat?.messages]);

    const handleSendMessage = () => {
        if (!inputValue.trim()) return;
        addMessage(chatId, "user", inputValue);
        setInputValue("");
    };

    if (!chat) {
        return (
            <div className="flex items-center justify-center h-full text-muted-foreground">
                Chat not found.
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full bg-background relative overflow-hidden">
            {/* Messages Area - ensure it takes full space and handles own scrolling */}
            <div className="flex-1 min-h-0 relative">
                <ScrollArea ref={scrollRef} className="h-full w-full">
                    <div className="max-w-3xl mx-auto space-y-8 px-4 py-8 pb-40">
                        {chat.messages.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-[60vh] text-center space-y-4">
                                <div className="bg-primary/10 p-4 rounded-full animate-in fade-in zoom-in duration-500">
                                    <Sparkles className="size-8 text-primary" />
                                </div>
                                <h2 className="text-2xl font-bold">How can I help you today?</h2>
                                <p className="text-muted-foreground max-w-sm">
                                    Ask me anything about our products, store locations, or order status.
                                </p>
                            </div>
                        ) : (
                            chat.messages.map((message) => (
                                <div
                                    key={message.id}
                                    className={cn(
                                        "flex gap-4 group animate-in slide-in-from-bottom-2 duration-300",
                                        message.role === "user" ? "justify-end" : "justify-start"
                                    )}
                                >
                                    {message.role === "assistant" && (
                                        <Avatar className="size-8 border bg-primary/10 shrink-0">
                                            <AvatarFallback><Bot className="size-4" /></AvatarFallback>
                                            <AvatarImage src="/bot-avatar.png" />
                                        </Avatar>
                                    )}
                                    <div
                                        className={cn(
                                            "max-w-[80%] rounded-2xl px-4 py-3 text-sm shadow-sm transition-all",
                                            message.role === "user"
                                                ? "bg-primary text-primary-foreground rounded-tr-none"
                                                : "bg-muted text-foreground rounded-tl-none border border-border/50"
                                        )}
                                    >
                                        <div className="prose prose-sm dark:prose-invert max-w-none break-words leading-relaxed overflow-hidden">
                                            <ReactMarkdown
                                                remarkPlugins={[remarkGfm]}
                                                components={{
                                                    pre: ({ ...props }) => (
                                                        <div className="overflow-auto my-2 w-full rounded-lg bg-black/10 dark:bg-white/5 p-3 text-xs border border-border/50">
                                                            <pre {...props} />
                                                        </div>
                                                    ),
                                                    code: ({ ...props }) => {
                                                        return <code className="bg-black/10 dark:bg-white/10 rounded px-1" {...props} />;
                                                    },
                                                    ul: ({ ...props }) => <ul className="list-disc ml-4 my-2" {...props} />,
                                                    ol: ({ ...props }) => <ol className="list-decimal ml-4 my-2" {...props} />,
                                                    p: ({ ...props }) => <p className="mb-2 last:mb-0" {...props} />,
                                                    h3: ({ ...props }) => <h3 className="text-base font-bold my-2" {...props} />,
                                                }}
                                            >
                                                {message.content}
                                            </ReactMarkdown>
                                        </div>
                                        <div className={cn(
                                            "text-[10px] mt-2 opacity-50 font-medium",
                                            message.role === "user" ? "text-right" : "text-left"
                                        )}>
                                            {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                        </div>
                                    </div>
                                    {message.role === "user" && (
                                        <Avatar className="size-8 border bg-muted shrink-0">
                                            <AvatarFallback><User className="size-4" /></AvatarFallback>
                                        </Avatar>
                                    )}
                                </div>
                            ))
                        )}
                    </div>
                </ScrollArea>

                {/* Fixed Floating Input Area at the bottom of the message container */}
                <div className="absolute bottom-0 left-0 right-0 z-10">
                    <div className="bg-gradient-to-t from-background via-background/95 to-transparent pt-12 pb-6 px-4">
                        <div className="max-w-3xl mx-auto relative group">
                            <div className="absolute -inset-1 bg-gradient-to-r from-primary/20 to-primary/10 rounded-2xl blur opacity-25 group-focus-within:opacity-100 transition duration-1000 group-hover:duration-200"></div>
                            <div className="relative flex items-center bg-background border rounded-2xl p-1.5 shadow-xl focus-within:ring-2 ring-primary/20 transition-all border-border/80">
                                <Input
                                    placeholder="Message AI Assistant..."
                                    className="border-none focus-visible:ring-0 focus-visible:ring-offset-0 bg-transparent text-base py-6 px-4 h-auto"
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter" && !e.shiftKey) {
                                            e.preventDefault();
                                            handleSendMessage();
                                        }
                                    }}
                                />
                                <Button
                                    size="icon"
                                    className={cn(
                                        "size-10 rounded-xl transition-all",
                                        inputValue.trim() ? "bg-primary scale-100" : "bg-muted text-muted-foreground scale-90"
                                    )}
                                    disabled={!inputValue.trim()}
                                    onClick={handleSendMessage}
                                >
                                    <SendHorizontal className="size-5" />
                                </Button>
                            </div>
                            <p className="text-[10px] text-center mt-3 text-muted-foreground font-medium uppercase tracking-wider opacity-60">
                                Powered by LLM Chat Engine
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
